  const dst = new Array(s.n);
  let i = 0;
  const st = [s.r, s.l];
  while (st.length !== 0) {
    const t = st.pop();
    if (t.a !== null) {
      const a = t.a, o = t.o, n = t.n;
      for (let k = 0; k < n; k++) dst[i++] = a[o + k];
    } else {
      st.push(t.r); st.push(t.l);
    }
  }
  s.a = dst; s.o = 0; s.l = null; s.r = null;
  return s;
